SET FOREIGN_KEY_CHECKS = 0;
USE phsoftme_erp_demo;


CREATE OR REPLACE VIEW MKM_VMember As
 SELECT
        M.Id            ,
        S.Id              Status_Id         , S.Name           Status_Name      ,
        C.Id              City_id           , C.Name           City_Name        ,
        A.Id              Country_id        , A.Name           Country_Name     ,
        U.User_Id       , U.User_Name       , U.Grp_Id       , U.Grp_Name       ,
        U.Grp_PStatus_Id, U.Grp_PStatus_Name, U.Grp_Status_Id, U.Grp_Status_Name,
        U.Grp_Rem       , U.User_Picture    , U.User_Logon   , U.User_Pass      ,
        U.User_Rem      , U.UGrp_Id         , U.UGrp_Name    , U.Gender_Id      ,
        U.Gender_Name   , U.Status_Id         User_Status_Id , U.Status_Name      User_Status_Name    ,
        M.Points        , M.nLong           , M.nLat         ,
        M.Mobile        , M.FName           , M.LName        , M.Email          ,
        M.Name          , M.Address         , M.Rem
   From MKM_Member      M
   Join Cpy_VUser       U On M.User_Id    = U.User_Id
   Join Phs_Cod_Status  S On M.Status_Id  = S.Id
   Join MKM_Cod_Cntry   A On M.Country_id = A.Id
   Join MKM_Cod_City    C On M.City_id    = C.Id;

CREATE OR REPLACE VIEW MKM_VUser_Profile AS
 SELECT
        W.User_Id     ,
        U.UGrp_Id     AS Kind_Id       , U.UGrp_Name   AS Kind_Name       ,
        W.Status_id   AS Status_Id     , S.Name        AS Status_Name     ,
        U.Status_Id   AS User_Status_Id, U.Status_Name AS User_Status_Name,
        W.Mobile      ,  W.FName       , W.LName       ,  W.Email         ,
        W.Name        ,  W.Address     , W.Rem         ,
        W.Country_id  AS Country_Id    , Ctry.Name     AS Country_Name    ,
        W.City_id     AS City_Id       , Ct.Name       AS City_Name       ,
        W.nLat        ,  W.nLong       , W.Points                         ,
        U.Verified_Id
   FROM MKM_Member         W
   JOIN Cpy_VUser          U    ON W.User_Id    = U.User_Id
   JOIN Phs_Cod_Status     S    ON W.Status_id  = S.Id
   JOIN MKM_Cod_City       Ct   ON W.City_id    = Ct.Id
   JOIN MKM_Cod_Cntry      Ctry ON W.Country_id = Ctry.Id 
  UNION ALL
 SELECT
        U.User_Id     ,
        U.UGrp_Id     AS Kind_Id       , U.UGrp_Name   AS Kind_Name       ,
        NULL          AS Status_Id     , NULL          AS Status_Name     ,
        U.Status_Id   AS User_Status_Id, U.Status_Name AS User_Status_Name,
        NULL          AS Mobile        , NULL          AS FName           , NULL AS LName, NULL AS Email,
        NULL          AS Name          , NULL          AS Address         , NULL AS Rem,
        NULL          AS Country_Id    , NULL          AS Country_Name    ,
        NULL          AS City_Id       , NULL          AS City_Name       ,
        NULL          AS nLat          , NULL          AS nLong           , NULL AS Points,
        U.Verified_Id
   FROM Cpy_VUser U
  WHERE U.UGrp_Id=1;

CREATE OR REPLACE VIEW MKM_VBrand As
SELECT
       B.Id       ,
       B.Status_Id, S.Name      Status_Name,
       B.Name1    , B.Name2   , B.Image    ,
       B.Ins_User , B.Ins_Date, B.Upd_User , B.Upd_Date,
       (Select Count(*) From MKM_Product P Where P.Brand_Id=B.Id) Product_Count
  From MKM_Brand     B
  Join Phs_Cod_Status S On B.Status_Id=S.Id;

CREATE OR REPLACE VIEW MKM_VCat As
SELECT
       C.Id       ,
       S.Id         Status_Id , S.Name      Status_Name,
       C.Order_Num, C.Wdays   , C.Points  ,
       C.Name1    , C.Name2   , C.Descrip , C.Image    ,
       C.Ins_User , C.Ins_Date, C.Upd_User, C.Upd_Date ,
       (Select Count(*) From MKM_Product P Where P.Cat_Id = C.Id) Product_Count
  From MKM_Cat    C
  Join Phs_Cod_Status    S On C.Status_Id  = S.Id;

CREATE OR REPLACE VIEW MKM_VProduct As
SELECT
       P.Id              ,
       P.Id                Product_Id      ,
       P.Mnum              Product_Num     ,
       P.Status_Id       , S.Name            Status_Name      ,
       P.Brand_Id        , B.Name1           Brand_Name1      , B.Name2        Brand_Name2       , B.Image    Brand_Image,
       P.Cat_Id          , C.Name1           Cat_Name1        , C.Name2        Cat_Name2         , C.Image    Cat_Image  ,
       P.Name1             Product_Name1   , P.Name2            Product_Name2,
       P.Qnt             , P.Price         , P.Cprice         ,
       P.Desc1           , P.Desc2         , P.Desc3          , P.Desc4      , P.Desc5,
       P.Image             Product_Image   ,
       P.Ins_User        , P.Ins_Date      , P.Upd_User       , P.Upd_Date
  From MKM_Product      P
  Join Phs_Cod_Status    S On P.Status_Id  = S.Id
  Join MKM_Brand        B On P.Brand_Id   = B.Id
  Join MKM_Cat    C On P.Cat_Id     = C.Id;

CREATE OR REPLACE VIEW MKM_VProd_Serial As
SELECT
       PS.Id        ,
       PS.Id          Serial_Id    ,
       PS.Prod_Id   , P.Name1        Prod_Name1 , P.Name2      Prod_Name2 ,
       P.Brand_Id   , B.Name1        Brand_Name1, B.Name2      Brand_Name2,
       P.Cat_Id     , C.Name1        Cat_Name1  , C.Name2      Cat_Name2  ,
       PS.Serial      Serial_Number,
       PS.Qnt       , PS.Cqnt      ,
       PS.Created_At,
       PS.Ins_User  , PS.Ins_Date  , PS.Upd_User, PS.Upd_Date
  From MKM_Prod_Serial  PS
  Join MKM_Product      P  On PS.Prod_Id=P.Id
  Join MKM_Brand        B  On P.Brand_Id=B.Id
  Join MKM_Cat    C  On P.Cat_Id  =C.Id;

CREATE OR REPLACE VIEW MKM_VSale As
SELECT
       S.Id              ,
       S.Id                Sale_Id          ,
       S.Bran_Id         , B.Name             Bran_Name        ,
       S.Mdate             Sale_Date        ,
       S.Customer        , S.Address       , S.Mobile        ,
       S.Ins_User        , S.Ins_Date       , S.Upd_User       , S.Upd_Date,
       (Select Count(*) From MKM_Sales_Item SI Where SI.Sales_Id = S.Id) Items_Count
  From MKM_Sale         S
  Left Join Cpy_Bran B On S.Bran_Id = B.Id;

CREATE OR REPLACE VIEW MKM_VSales_Item As
SELECT
       SI.Id      ,
       SI.Id        Item_Id    ,
       SI.Sales_Id, S.Customer , S.Mobile   , S.Mdate      Sale_Date  ,
       SI.Prod_Id , P.Name1      Prod_Name1 , P.Name2      Prod_Name2 ,
       P.Brand_Id , B.Name1      Brand_Name1, B.Name2      Brand_Name2,
       P.Cat_Id   , C.Name1      Cat_Name1  , C.Name2      Cat_Name2  ,
       SI.Serial  , SI.Wdays   , SI.Edate   ,
       SI.Ins_User, SI.Ins_Date, SI.Upd_User, SI.Upd_Date
  From MKM_Sales_Item   SI
  Join MKM_Sale         S  On SI.Sales_Id = S.Id
  Join MKM_Product      P  On SI.Prod_Id  = P.Id
  Join MKM_Brand        B  On P.Brand_Id  = B.Id
  Join MKM_Cat    C  On P.Cat_Id    = C.Id;

CREATE OR REPLACE VIEW MKM_VTicket As
SELECT
       T.Id         ,
       T.Id           Ticket_Id     ,
       T.Sale_Id    , S.Customer    , S.Mobile ,
       S.Mdate        Sale_Date     ,
       TS.Id          Status_Id     , TS.Name     Status_Name,
       U.Id           User_Id       , U.Name      User_Name  ,
       T.Tdate        Ticket_Date   , T.Udate     Update_Date,
       T.Ticket_Text, T.Support_Text,
       T.Ins_User   , T.Ins_Date    , T.Upd_User, T.Upd_Date
  From MKM_Ticket     T
  Join MKM_Sale       S  On T.Sale_Id  =S.Id
  Join MKM_Cod_TStatus TS On T.Status_Id=TS.Id
  Join Cpy_User        U  On T.User_Id  =U.Id;

CREATE OR REPLACE VIEW MKM_VMInstallment As
 SELECT
        I.Id         ,
        I.Id           Installment_Id    ,
        M.Id           Member_Id         ,
        M.Status_Id    Member_Status_Id  , M.Status_Name  Member_Status_Name ,
        M.User_Id      Member_User_Id    , M.User_Name    Member_User_Name   ,
        M.User_Logon   Member_User_Logon ,
        M.City_id      Member_City_id    , M.City_Name    Member_City_Name   ,
        M.Country_id   Member_Country_id , M.Country_Name Member_Country_Name,
        M.nLong        Member_nLong      , M.nLat         Member_nLat        ,
        M.Points       Member_Points     , M.Mobile       Member_Mobile      ,
        M.FName        Member_FName      , M.LName        Member_LName       ,
        M.Email        Member_Email      , M.Name         Member_Name        ,
        M.Address      Member_Address    , M.Rem          Member_Rem         ,
        S.Id           Status_Id         , S.Name         Status_Name        ,
        T.Prod_Id    , T.Serial          , I.Mobile     , I.dDate            ,
        T.Points     , I.Name            , I.Address    , I.Rem
   From MKM_MInstallment  I
   Join MKM_Inst_Items    T  On T.Inst_Id    = I.Id
   Join MKM_VMember       M  On I.User_Id    = M.User_Id
   Join MKM_Cod_IStatus   S  On I.Status_Id  = S.Id;

CREATE OR REPLACE VIEW MKM_VSerialFull AS
SELECT 
    -- 1. Product Details (Always present)
    ps.Serial,
    p.Id    AS Prod_Id   ,
    p.Name1 AS Prod_Name1,
    p.Name2 AS Prod_Name2,
    p.Price,
    p.Cprice,
    p.Desc1,
    p.Desc2,
    p.Desc3,
    p.Desc4,
    p.Desc5,
    p.Image AS Prod_Image,
    
    -- Brand & Category
    b.Id    AS Brand_Id,
    b.Name1 AS Brand_Name,
    c.Id    AS Cat_Id,
    c.Name1 AS Cat_Name1,
    c.Name2 AS Cat_Name2,
    c.Wdays AS Cat_Wdays,

    -- 2. Sale Status
    CASE WHEN si.Id IS NOT NULL THEN 'true' ELSE 'false' END AS isSale,
    s.Bran_Id,
    s.Mdate AS Sale_Date,
    s.Customer,
    s.Address,
    s.Mobile,
    s.Ins_User AS Sale_Ins_User,
    
    -- Sales Item Details
    si.Id     AS Sale_Item_Id,
    si.Serial AS Sale_Serial,
    si.Wdays  AS Sale_Wdays,
    si.Edate  AS Sale_Edate,

    -- 3. Installment Status
    CASE WHEN ii.Id IS NOT NULL THEN 'true' ELSE 'false' END AS isInst,
    mi.Id        AS Installment_Id,
    mi.Status_Id AS Inst_Status_Id,
    mi.dDate     AS Inst_Date,
    mi.Name      AS Inst_Customer_Name,
    mi.Mobile    AS Inst_Mobile,
    mi.Address   AS Inst_Address,
    mi.Rem       AS Inst_Rem,
    
    -- Installment Item Details
    ii.Id     AS Inst_Item_Id,
    ii.Serial AS Inst_Serial,
    ii.Points AS Inst_Points,

    -- 4. Ticket Status 
    CASE WHEN t.Id IS NOT NULL THEN 'true' ELSE 'false' END AS isTicket,
    t.Id        AS Ticket_Id,
    t.Status_Id AS Ticket_Status_Id,
    t.Ticket_Text,
    t.Support_Text,
    t.Tdate     AS Ticket_Date

 FROM MKM_Prod_Serial ps
 JOIN MKM_Product p                 ON ps.Prod_Id = p.Id
 JOIN MKM_Brand b                   ON p.Brand_Id = b.Id
 JOIN MKM_Cat c               ON p.Cat_Id = c.Id
 LEFT JOIN MKM_Sales_Item si        ON ps.Serial = si.Serial
 LEFT JOIN MKM_Sale s               ON si.Sales_Id = s.Id
 LEFT JOIN MKM_Inst_Items ii ON ps.Serial = ii.Serial
 LEFT JOIN MKM_MInstallment mi       ON ii.Inst_Id = mi.Id
 LEFT JOIN MKM_Ticket t             ON s.Id = t.Sale_Id;
